#!/usr/bin/env python3
"""
Create a complete OpenFOAM 10 (Foundation) case for a 3D Bernard cell
(Rayleigh-Benard convection) simulation using the buoyantFoam solver.

Domain : 9 m (x) x 1 m (y, vertical) x 2 m (z)
Bottom wall (hot) : 310 K
Top wall (cold)   : 295 K
Side walls        : adiabatic, no-slip
Time              : 0 s -> 1000 s, deltaT = 1 s, output every 50 s

The script only writes the case files (no OpenFOAM commands are executed).
Run the case afterwards with:  ./Allrun
"""

import os

# ---------------------------------------------------------------------------
# small helpers (only os / built-ins are used)
# ---------------------------------------------------------------------------

def write_file(rel_path, content):
    """Write `content` to `rel_path`, creating parent directories as needed."""
    directory = os.path.dirname(rel_path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    with open(rel_path, "w") as handle:
        handle.write(content)


def foam_file(cls, location, obj):
    """Return a standard OpenFOAM 10 (Foundation) FoamFile header."""
    return (
        "FoamFile\n"
        "{\n"
        "    version     10;\n"
        "    format      ascii;\n"
        "    class       " + cls + ";\n"
        '    location    "' + location + '";\n'
        "    object      " + obj + ";\n"
        "}\n"
        "// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n"
        "\n"
    )


def field_file(cls, name, dimensions, internal_field, bc_for_patch, patches):
    """Return the content of a time = 0 field file."""
    text = foam_file(cls, "0", name)
    text += "dimensions      " + dimensions + ";\n\n"
    text += "internalField   " + internal_field + ";\n\n"
    text += "boundaryField\n{\n"
    for patch in patches:
        text += "    " + patch + "\n    {\n"
        for line in bc_for_patch(patch):
            text += "        " + line + "\n"
        text += "    }\n\n"
    text += "}\n\n"
    text += "//************************************************************************* //\n"
    return text


